"""T-005 r4 9.5d: speed ladder with re-optimised v3 rows at Fr 0.07 / 0.08 / 0.09 (stride_opt_tc.py --lat --trans --v3, FEASIBLE, b5 criterion A walked).
Runs Tools/GaitOpt/export_reference_v2.py (unchanged) per stride and writes Assets/Game/Config/Mech/gait_reference_qp_ladder_v3.json (rows sorted by Froude: 0.02 0.04 0.06 0.07 0.08 0.09);
gait_reference_qp.json (the Fr 0.10 row) is restored byte for byte; gait_reference_qp_ladder.json is untouched. Run from the project root."""
import json, pathlib, subprocess, sys
ROOT = pathlib.Path.cwd(); MAIN = ROOT / "Assets/Game/Config/Mech/gait_reference_qp.json"; OUT = ROOT / "Assets/Game/Config/Mech/gait_reference_qp_ladder_v3.json"
SRC = ["stride_fr002_lat.json", "stride_fr004_lat.json", "stride_fr006_lat.json", "stride_fr007_v3_a.json", "stride_fr008_v3_a.json", "stride_fr009_v3_a.json"]
keep = MAIN.read_bytes() if MAIN.exists() else None; rows = []; base = None
try:
    for s in SRC:
        subprocess.run([sys.executable, "Tools/GaitOpt/export_reference_v2.py", f"Tools/GaitOpt/out/{s}"], check=True)
        d = json.loads(MAIN.read_text()); rows += d["rows"]; base = base or d
finally:
    MAIN.write_bytes(keep) if keep is not None else MAIN.unlink(missing_ok=True)
base["rows"] = rows; base["notes"] = "Speed ladder of the imp 3 start (T-005 r4 9.5d, qp_ladder): @v2 rows Fr 0.02-0.06 (9.5b) plus v3 re-optimised Fr 0.07 / 0.08 / 0.09; generated by evidence/T-005/round4/scripts/export_ladder95d.py; do not edit by hand."
base["source"]["files"] = SRC; base["source"]["verdicts"] = [f"{r['source_file']}: {r['verdict']}, fr {r['fr']}" for r in rows]
OUT.write_text(json.dumps(base, indent=1)); print("wrote", OUT, [(r["fr"], r["verdict"], round(r["v"], 2), round(r["step_length_m"], 1)) for r in rows])
